export const educationBaselineHtml = "<!-- ===================== EDUCATION — SECTION SUB NAV (STICKY TABS) | CLONE OF INSURANCE ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --tabText:#6B7280;\n    --tabActive: var(--indigo);\n    --line:#E6E8EF;\n    --bg:#ffffff;\n\n    /* Height of this subnav (kept as a variable for scroll offset) */\n    --eduSecTabsH: 58px;\n  }\n\n  .eduTabs, .eduTabs *{box-sizing:border-box;}\n\n  /* Sticky subnav only */\n  .eduTabs{\n    position:sticky;\n    top:0;\n    z-index:9999;\n    background:var(--bg);\n    border-bottom:1px solid var(--line);\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    isolation:isolate;\n  }\n\n  .eduTabs__inner{\n    max-width:1200px;\n    margin:0 auto;\n    padding:0 20px;\n    height:var(--eduSecTabsH);\n    display:flex;\n    align-items:center;\n    gap:14px;\n  }\n\n  .eduTabs__label{\n    font-weight:900;\n    letter-spacing:.08em;\n    text-transform:uppercase;\n    color:#111;\n    font-size:12px;\n    padding-right:14px;\n    border-right:1px solid var(--line);\n    margin-right:2px;\n    white-space:nowrap;\n  }\n\n  .eduTabs__list{\n    display:flex;\n    align-items:center;\n    gap:0;\n    flex-wrap:nowrap;\n    overflow:auto;\n    scrollbar-width:none;\n  }\n  .eduTabs__list::-webkit-scrollbar{display:none;}\n\n  .eduTabs__link{\n    position:relative;\n    display:inline-flex;\n    align-items:center;\n    height:var(--eduSecTabsH);\n    padding:0 18px;\n    text-decoration:none;\n    text-transform:uppercase;\n    letter-spacing:.06em;\n    font-size:12px;\n    font-weight:800;\n    color:var(--tabText);\n    white-space:nowrap;\n  }\n\n  /* vertical separators */\n  .eduTabs__link + .eduTabs__link{\n    border-left:1px solid var(--line);\n  }\n\n  /* active underline */\n  .eduTabs__link.is-active{\n    color:var(--tabActive);\n  }\n  .eduTabs__link.is-active::after{\n    content:\"\";\n    position:absolute;\n    left:14px;\n    right:14px;\n    bottom:0;\n    height:3px;\n    background:var(--tabActive);\n    border-radius:999px;\n  }\n\n  .eduTabs__link:hover{ color:#111; }\n\n  /* Optional: add this class to each target section wrapper if you want:\n     <section id=\"...\" class=\"eduAnchorFix\"> ... */\n  .eduAnchorFix{ scroll-margin-top: calc(var(--eduSecTabsH) + 14px); }\n\n  @media(max-width:980px){\n    .eduTabs__inner{padding:0 14px;}\n    .eduTabs__label{display:none;}\n    .eduTabs__link{padding:0 14px;}\n  }\n</style>\n\n<nav class=\"eduTabs\" aria-label=\"Education page navigation\">\n  <div class=\"eduTabs__inner\">\n    <div class=\"eduTabs__label\">EDUCATION</div>\n\n    <div class=\"eduTabs__list\">\n      <!-- Update IDs only if your section IDs differ -->\n      <a class=\"eduTabs__link is-active\" href=\"#edu-hero\">Overview</a>\n      <a class=\"eduTabs__link\" href=\"#edu-challenges\">Key Challenges</a>\n      <a class=\"eduTabs__link\" href=\"#edu-how-we-help\">How We Help</a>\n      <a class=\"eduTabs__link\" href=\"#edu-collab-why\">Collaboration &amp; Why Us</a>\n      <a class=\"eduTabs__link\" href=\"#edu-cta\">Next Steps</a>\n    </div>\n  </div>\n</nav>\n\n<script>\n(function(){\n  const nav = document.querySelector('.eduTabs');\n  if(!nav) return;\n\n  const links = Array.from(nav.querySelectorAll('.eduTabs__link'));\n  const getOffset = () => {\n    const h = nav.getBoundingClientRect().height || 58;\n    return h + 12; // small breathing space so title is visible\n  };\n\n  // Smooth scroll with correct offset so sections are NOT hidden under sticky tabs\n  links.forEach(a=>{\n    a.addEventListener('click', (e)=>{\n      const href = a.getAttribute('href');\n      if(!href || !href.startsWith('#')) return;\n\n      const el = document.querySelector(href);\n      if(!el) return;\n\n      e.preventDefault();\n      const y = el.getBoundingClientRect().top + window.pageYOffset - getOffset();\n      window.scrollTo({ top:y, behavior:'smooth' });\n      history.replaceState(null, '', href);\n    });\n  });\n\n  // Active state on scroll\n  const targets = links\n    .map(a => document.querySelector(a.getAttribute('href')))\n    .filter(Boolean);\n\n  const setActive = (id) => {\n    links.forEach(a=>{\n      a.classList.toggle('is-active', a.getAttribute('href') === '#'+id);\n    });\n  };\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  if(isElementor) return;\n  if(!('IntersectionObserver' in window)) return;\n\n  const io = new IntersectionObserver((entries)=>{\n    const visible = entries\n      .filter(e=>e.isIntersecting)\n      .sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];\n\n    if(visible && visible.target && visible.target.id){\n      setActive(visible.target.id);\n    }\n  }, { root:null, threshold:[0.2,0.35,0.5,0.65] });\n\n  targets.forEach(t=>{\n    if(t.id) io.observe(t);\n  });\n})();\n</script>\n\n<!-- ===================== EDUCATION — HERO (WHITE ONLY) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    /* ✅ only agreed brand colours */\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#3C4160;\n    --line:rgba(49,59,134,.16);\n    --white:#ffffff;\n\n    --max:1200px;\n  }\n\n  .eduHero, .eduHero *{box-sizing:border-box;}\n  .eduHero{\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    background:#fff;\n    padding:88px 20px 34px;\n  }\n\n  .eduHero__inner{\n    max-width:var(--max);\n    margin:0 auto;\n    display:grid;\n    grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);\n    gap:44px;\n    align-items:center;\n  }\n\n  .eduHero__eyebrow{\n    margin:0 0 12px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .eduHero__title{\n    margin:0 0 14px;\n    font-size:clamp(34px,4.2vw,56px);\n    line-height:1.06;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .eduHero__sub{\n    margin:0 0 14px;\n    font-size:clamp(16px,2vw,20px);\n    line-height:1.55;\n    font-weight:700;\n    color:var(--indigo);\n    max-width:820px;\n  }\n\n  .eduHero__p{\n    margin:0;\n    font-size:15.5px;\n    line-height:1.78;\n    color:var(--muted);\n    max-width:920px;\n  }\n  .eduHero__p + .eduHero__p{ margin-top:14px; }\n\n  /* Right visual (image placeholder) */\n  .eduHero__media{\n    border-radius:22px;\n    overflow:hidden;\n    border:1px solid var(--line);\n    box-shadow:0 18px 44px rgba(0,0,0,.08);\n    background:\n      radial-gradient(circle at 20% 15%, rgba(98,90,216,.22), transparent 55%),\n      radial-gradient(circle at 85% 25%, rgba(31,156,228,.22), transparent 55%),\n      radial-gradient(circle at 50% 95%, rgba(49,59,134,.18), transparent 60%),\n      linear-gradient(180deg, rgba(2,12,79,.06), rgba(49,59,134,.04));\n    min-height:320px;\n    position:relative;\n  }\n\n  .eduHero__img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:cover; /* ✅ fills container */\n  }\n\n  .eduHero__badge{\n    position:absolute;\n    left:16px; top:16px;\n    display:inline-flex;\n    align-items:center;\n    gap:10px;\n    padding:10px 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.18);\n    background:rgba(255,255,255,.76);\n    backdrop-filter:blur(8px);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:900;\n  }\n  .eduHero__dot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.12);\n  }\n\n  @media (max-width:980px){\n    .eduHero{padding:74px 16px 22px;}\n    .eduHero__inner{grid-template-columns:1fr; gap:22px;}\n    .eduHero__media{min-height:240px;}\n  }\n</style>\n\n<section class=\"eduHero\" id=\"edu-hero\">\n  <div class=\"eduHero__inner\">\n    <!-- LEFT CONTENT -->\n    <div>\n      <p class=\"eduHero__eyebrow\">Education Sector – Industry Solutions &amp; Transformation Services</p>\n\n      <h1 class=\"eduHero__title\">Education Sector – Shaping the Next Generation of Value Creators</h1>\n\n      <p class=\"eduHero__sub\">Partnering to build a future-ready workforce for India.</p>\n\n      <p class=\"eduHero__p\">\n        India stands at a once-in-a-generation inflection point. With Industry 4.0, AI, automation, entrepreneurship,\n        and global competitiveness accelerating, our youth must be equipped with the skills, mindset, and methodologies\n        that shape tomorrow’s world.\n      </p>\n      <p class=\"eduHero__p\">\n        At [Your Firm Name], we believe that strengthening the education ecosystem is not just a service—it’s a national mission.\n        We partner with higher education institutions, universities, skill development bodies, and vocational institutes to\n        prepare the soil, enabling young minds to become the Lean leaders, digital thinkers, problem solvers, and value creators India needs.\n      </p>\n      <p class=\"eduHero__p\">\n        This is not a transactional engagement. This is collaboration for transformation.\n      </p>\n    </div>\n\n    <!-- RIGHT VISUAL -->\n    <div class=\"eduHero__media\">\n      <div class=\"eduHero__badge\"><span class=\"eduHero__dot\"></span> Education &amp; Skills Transformation</div>\n      <img\n        class=\"eduHero__img\"\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Education and skills ecosystem transformation (placeholder)\"\n      />\n    </div>\n  </div>\n</section>\n\n<!-- ===================== EDUCATION — KEY CHALLENGES (DESKTOP: LIST + DETAIL | MOBILE: CARD ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n  :root{\n    --navy:#020C4F;\n    --indigo:#313B86;\n    --violet:#625AD8;\n    --accent:#1F9CE4;\n\n    --ink:#0B0F1A;\n    --muted:#4B5168;\n    --line:rgba(49,59,134,.16);\n    --card:#fff;\n  }\n\n  .adK, .adK *{ box-sizing:border-box; }\n\n  .adK{\n    position:relative;\n    padding:92px 20px;\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n    color:var(--ink);\n    overflow:hidden;\n    background:\n      radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 95% 30%, rgba(49,59,134,.10), transparent 55%),\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n      rgba(49,59,134,.03);\n  }\n\n  .adK__inner{ max-width:1200px; margin:0 auto; position:relative; }\n\n  .adK__top{\n    display:grid;\n    grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);\n    gap:32px;\n    align-items:start;\n    margin-bottom:22px;\n  }\n\n  .adK__eyebrow{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n    margin:0 0 10px;\n  }\n\n  .adK__title{\n    margin:0;\n    font-size:clamp(38px,4.4vw,56px);\n    line-height:1.05;\n    font-weight:900;\n    color:var(--navy);\n  }\n\n  .adK__intro{\n    margin:22px 0 0;\n    font-size:15.5px;\n    line-height:1.75;\n    color:#3C4160;\n    max-width:780px;\n  }\n\n  .adK__grid{\n    display:grid;\n    grid-template-columns:minmax(0,.86fr) minmax(0,1.14fr);\n    gap:26px;\n    align-items:stretch;\n    margin-top:18px;\n  }\n\n  /* LEFT RAIL (desktop/tablet) */\n  .adK__rail{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.78);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    min-width:0;\n  }\n\n  .adK__railTop{\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:14px;\n    padding:16px 16px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n  }\n\n  .adK__railLabel{\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--navy);\n    font-weight:900;\n  }\n\n  .adK__railPill{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:32px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.85);\n    font-size:12px;\n    font-weight:800;\n    color:var(--indigo);\n    white-space:nowrap;\n  }\n  .adK__railPillDot{\n    width:10px;height:10px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    box-shadow:0 0 0 5px rgba(31,156,228,.10);\n  }\n\n  .adK__item{\n    width:100%;\n    display:grid;\n    grid-template-columns:44px 1fr;\n    gap:12px;\n    align-items:center;\n    padding:14px 16px;\n    background:transparent;\n    border:0;\n    border-top:1px solid rgba(49,59,134,.10);\n    cursor:pointer;\n    text-align:left;\n    transition:background .18s ease;\n    min-width:0;\n    white-space:normal !important;\n  }\n  .adK__item:first-of-type{ border-top:0; }\n  .adK__item:hover{ background:rgba(49,59,134,.03); }\n\n  .adK__icon{\n    width:40px;height:40px;\n    border-radius:14px;\n    display:grid;\n    place-items:center;\n    background:rgba(49,59,134,.05);\n    border:1px solid rgba(49,59,134,.14);\n    font-size:18px;\n  }\n\n  .adK__textCol{ min-width:0 !important; }\n\n  .adK__itemTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    color:var(--navy);\n    line-height:1.25;\n    white-space:normal !important;\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n    max-width:100% !important;\n  }\n\n  /* 2-line preview */\n  .adK__itemPreview{\n    margin:4px 0 0;\n    font-size:13px;\n    line-height:1.5;\n    color:#5B6282;\n\n    display:-webkit-box !important;\n    -webkit-box-orient:vertical !important;\n    -webkit-line-clamp:2 !important;\n    overflow:hidden !important;\n    text-overflow:ellipsis !important;\n    white-space:normal !important;\n\n    overflow-wrap:anywhere !important;\n    word-break:break-word !important;\n    min-width:0;\n    max-width:100%;\n  }\n\n  /* Accordion content hidden by default (desktop/tablet) */\n  .adK__acc{ display:none; }\n\n  .adK__item[aria-selected=\"true\"]{\n    background:rgba(31,156,228,.06);\n    position:relative;\n  }\n  .adK__item[aria-selected=\"true\"]::before{\n    content:\"\";\n    position:absolute;\n    left:0; top:0; bottom:0;\n    width:4px;\n    background:linear-gradient(180deg,var(--accent),var(--violet));\n  }\n  .adK__item[aria-selected=\"true\"] .adK__icon{\n    border-color:rgba(31,156,228,.28);\n    background:rgba(31,156,228,.08);\n  }\n\n  /* RIGHT PANEL (desktop/tablet) */\n  .adK__panel{\n    border:1px solid rgba(49,59,134,.18);\n    border-radius:22px;\n    background:rgba(255,255,255,.86);\n    backdrop-filter:blur(10px);\n    box-shadow:0 18px 44px rgba(0,0,0,.06);\n    overflow:hidden;\n    display:flex;\n    flex-direction:column;\n    min-width:0;\n    min-height:520px;\n  }\n\n  .adK__panelHead{\n    padding:16px 18px 14px;\n    border-bottom:1px solid rgba(49,59,134,.12);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 60%),\n      rgba(255,255,255,.85);\n  }\n\n  .adK__panelKicker{\n    margin:0 0 6px;\n    font-size:12px;\n    letter-spacing:.18em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .adK__panelTitle{\n    margin:0;\n    font-size:22px;\n    line-height:1.25;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .adK__panelBody{ padding:18px; flex:1 1 auto; }\n\n  .adK__bullets{\n    margin:0;\n    padding:0;\n    list-style:none;\n    display:grid;\n    gap:12px;\n  }\n\n  .adK__bullets li{\n    display:flex;\n    gap:10px;\n    align-items:flex-start;\n    font-size:14.5px;\n    line-height:1.65;\n    color:#2E334D;\n    min-width:0;\n  }\n\n  .adK__dot{\n    width:10px;height:10px;border-radius:999px;\n    margin-top:7px;\n    flex:0 0 auto;\n    background:rgba(31,156,228,.22);\n    outline:3px solid rgba(31,156,228,.10);\n  }\n\n  .adK__bullets li span:last-child{\n    min-width:0;\n    overflow-wrap:anywhere;\n    word-break:break-word;\n  }\n\n  .adK__panelFooter{\n    padding:14px 16px;\n    border-top:1px solid rgba(49,59,134,.12);\n    background:rgba(255,255,255,.75);\n    display:flex;\n    flex-wrap:wrap;\n    gap:10px;\n  }\n\n  .adK__chip{\n    display:inline-flex;\n    align-items:center;\n    gap:8px;\n    height:34px;\n    padding:0 12px;\n    border-radius:999px;\n    border:1px solid rgba(49,59,134,.16);\n    background:rgba(255,255,255,.9);\n    color:var(--navy);\n    font-size:12px;\n    font-weight:800;\n    max-width:100%;\n  }\n  .adK__chip i{\n    width:7px;height:7px;border-radius:999px;\n    background:linear-gradient(135deg,var(--violet),var(--accent));\n    display:inline-block;\n  }\n\n  .adK__fade{\n    opacity:1;\n    transform:translateY(0);\n    transition:opacity .18s ease, transform .18s ease;\n  }\n  .adK__fade.is-switching{\n    opacity:0;\n    transform:translateY(6px);\n  }\n\n  @media (max-width:1024px){\n    .adK{ padding:78px 18px; }\n    .adK__top{ grid-template-columns:1fr; gap:14px; }\n    .adK__intro{ margin-top:0; }\n    .adK__grid{ grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr); gap:18px; }\n    .adK__panel{ min-height:unset; }\n  }\n\n  /* ===================== MOBILE: stacked card accordion ===================== */\n  @media (max-width:820px){\n    .adK{ padding:70px 16px; }\n    .adK__title{ font-size:clamp(30px,9vw,40px); }\n    .adK__intro{ font-size:14.8px; margin-top:10px; }\n\n    .adK__grid{ grid-template-columns:1fr; }\n\n    /* Hide the right panel on mobile */\n    .adK__panel{ display:none !important; }\n\n    /* Remove rail frame on mobile */\n    .adK__rail{\n      border:none;\n      background:transparent;\n      backdrop-filter:none;\n      box-shadow:none;\n      overflow:visible;\n    }\n\n    .adK__railTop{\n      padding:14px 14px;\n      border:1px solid rgba(49,59,134,.16);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 10px 26px rgba(0,0,0,.06);\n      margin-bottom:12px;\n    }\n\n    .adK__item{\n      border:1px solid rgba(49,59,134,.14);\n      border-radius:18px;\n      background:rgba(255,255,255,.86);\n      box-shadow:0 12px 28px rgba(0,0,0,.06);\n      margin:0 0 12px;\n      padding:14px 14px;\n      grid-template-columns:42px 1fr;\n      align-items:start;\n      max-width:100% !important;\n    }\n    .adK__item:first-of-type{ border-top:1px solid rgba(49,59,134,.14); }\n\n    .adK__icon{ width:38px;height:38px; border-radius:14px; margin-top:2px; }\n\n    /* kill desktop selected styling on mobile */\n    .adK__item[aria-selected=\"true\"]{ background:rgba(255,255,255,.86) !important; }\n    .adK__item[aria-selected=\"true\"]::before{ display:none !important; }\n\n    .adK__acc{\n      grid-column:1 / -1;\n      margin:10px 0 2px;\n      padding:12px 12px;\n      border-radius:16px;\n      border:1px solid rgba(49,59,134,.12);\n      background:rgba(49,59,134,.03);\n      display:none;\n      overflow:hidden !important;\n      max-width:100% !important;\n      min-width:0 !important;\n    }\n    .adK__item[aria-expanded=\"true\"] .adK__acc{ display:block; }\n\n    .adK__accBullets{\n      margin:0;\n      padding:0;\n      list-style:none;\n      display:grid;\n      gap:10px;\n      max-width:100% !important;\n      min-width:0 !important;\n    }\n    .adK__accBullets li{\n      display:flex !important;\n      align-items:flex-start !important;\n      gap:10px !important;\n      flex-wrap:wrap !important;\n      min-width:0 !important;\n      max-width:100% !important;\n      font-size:14px;\n      line-height:1.65;\n      color:#2E334D;\n    }\n    .adK__accBullets li .adK__dot{ flex:0 0 auto !important; }\n\n    .adK__accBullets li span:last-child{\n      flex:1 1 0% !important;\n      min-width:0 !important;\n      max-width:100% !important;\n      display:block !important;\n      white-space:normal !important;\n      overflow-wrap:anywhere !important;\n      word-break:break-word !important;\n    }\n\n    .adK__accChips{\n      margin-top:12px;\n      display:flex;\n      flex-wrap:wrap;\n      gap:10px;\n      max-width:100%;\n    }\n\n    .adK__chip{ height:32px; font-size:12px; padding:0 11px; }\n  }\n\n  /* ===================== FORCE MOBILE LAYOUT VIA CLASS (Elementor preview help) ===================== */\n  .adK.is-mobile{ padding:70px 16px !important; }\n  .adK.is-mobile .adK__grid{ grid-template-columns:1fr !important; }\n  .adK.is-mobile .adK__panel{ display:none !important; }\n  .adK.is-mobile .adK__rail{\n    border:none !important; background:transparent !important; box-shadow:none !important;\n    backdrop-filter:none !important; overflow:visible !important;\n  }\n  .adK.is-mobile .adK__railTop{\n    padding:14px 14px !important;\n    border:1px solid rgba(49,59,134,.14) !important;\n    border-radius:16px !important;\n    background:#fff !important;\n    box-shadow:0 10px 24px rgba(0,0,0,.06) !important;\n    margin-bottom:12px !important;\n  }\n  .adK.is-mobile .adK__item{\n    border:1px solid rgba(49,59,134,.12) !important;\n    border-radius:16px !important;\n    background:#fff !important;\n    box-shadow:0 12px 26px rgba(0,0,0,.06) !important;\n    margin:0 0 12px !important;\n    padding:14px 14px !important;\n    grid-template-columns:42px 1fr !important;\n    align-items:start !important;\n  }\n  .adK.is-mobile .adK__item[aria-selected=\"true\"]::before{ display:none !important; }\n  .adK.is-mobile .adK__item[aria-selected=\"true\"]{ background:#fff !important; }\n  .adK.is-mobile .adK__acc{\n    display:none;\n    grid-column:1 / -1;\n    margin:10px 0 0;\n    padding:12px 12px;\n    border-radius:14px;\n    border:1px solid rgba(49,59,134,.10);\n    background:rgba(49,59,134,.02);\n    overflow:hidden !important;\n  }\n  .adK.is-mobile .adK__item[aria-expanded=\"true\"] .adK__acc{ display:block !important; }\n  .adK.is-mobile .adK__chip{ height:32px !important; font-size:12px !important; padding:0 11px !important; }\n</style>\n\n<section class=\"adK\" id=\"edu-challenges\">\n  <div class=\"adK__inner\">\n\n    <div class=\"adK__top\">\n      <div>\n        <p class=\"adK__eyebrow\">Education Sector</p>\n        <h2 class=\"adK__title\">The Challenges Facing the Education Sector Today</h2>\n      </div>\n\n      <p class=\"adK__intro\">\n        Academic excellence alone is no longer enough. Institutions are grappling with curriculum–industry gaps,\n        fragmented learning models, faculty capability constraints, and limited exposure to real-world problem-solving.\n        These challenges highlight the need for industry-partnered learning, not classroom learning alone.\n      </p>\n    </div>\n\n    <div class=\"adK__grid\">\n\n      <!-- LEFT: list -->\n      <div class=\"adK__rail\" role=\"tablist\" aria-label=\"Education sector challenges list\">\n        <div class=\"adK__railTop\">\n          <div class=\"adK__railLabel\">Challenges</div>\n          <div class=\"adK__railPill\"><span class=\"adK__railPillDot\" aria-hidden=\"true\"></span>Academic &amp; industry view</div>\n        </div>\n\n        <button class=\"adK__item\" role=\"tab\" aria-selected=\"true\" aria-expanded=\"false\" data-key=\"c1\">\n          <div class=\"adK__icon\">🎓</div>\n          <div class=\"adK__textCol\">\n            <p class=\"adK__itemTitle\">Curriculum–Industry Gap</p>\n            <p class=\"adK__itemPreview\">Programs lag modern industry demands and students graduate knowledgeable but not job-ready.</p>\n          </div>\n          <div class=\"adK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"adK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c2\">\n          <div class=\"adK__icon\">🧩</div>\n          <div class=\"adK__textCol\">\n            <p class=\"adK__itemTitle\">Lack of Integrated Learning Approaches</p>\n            <p class=\"adK__itemPreview\">Lean, Agile, digital and behavioural skills are taught in silos, if at all.</p>\n          </div>\n          <div class=\"adK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"adK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c3\">\n          <div class=\"adK__icon\">👩‍🏫</div>\n          <div class=\"adK__textCol\">\n            <p class=\"adK__itemTitle\">Faculty Capability &amp; Resource Constraints</p>\n            <p class=\"adK__itemPreview\">Limited access to current methodologies, tools, case studies, and tech exposure.</p>\n          </div>\n          <div class=\"adK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"adK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c4\">\n          <div class=\"adK__icon\">🧪</div>\n          <div class=\"adK__textCol\">\n            <p class=\"adK__itemTitle\">Limited Practical, Hands-on Methodologies</p>\n            <p class=\"adK__itemPreview\">Few real-life projects, simulations, or experiential learning opportunities.</p>\n          </div>\n          <div class=\"adK__acc\" aria-hidden=\"true\"></div>\n        </button>\n\n        <button class=\"adK__item\" role=\"tab\" aria-selected=\"false\" aria-expanded=\"false\" data-key=\"c5\">\n          <div class=\"adK__icon\">🧭</div>\n          <div class=\"adK__textCol\">\n            <p class=\"adK__itemTitle\">Lack of Structured Models for Employability &amp; Future Skills</p>\n            <p class=\"adK__itemPreview\">No cohesive frameworks to create Lean practitioners, innovators, or digital leaders.</p>\n          </div>\n          <div class=\"adK__acc\" aria-hidden=\"true\"></div>\n        </button>\n      </div>\n\n      <!-- RIGHT: detail panel (desktop only) -->\n      <aside class=\"adK__panel\" role=\"tabpanel\" aria-live=\"polite\">\n        <div class=\"adK__fade\" id=\"adK-fade\">\n          <div class=\"adK__panelHead\">\n            <p class=\"adK__panelKicker\">Challenge Focus</p>\n            <h3 class=\"adK__panelTitle\" id=\"adK-title\">Curriculum–Industry Gap</h3>\n          </div>\n\n          <div class=\"adK__panelBody\">\n            <ul class=\"adK__bullets\" id=\"adK-bullets\"></ul>\n          </div>\n\n          <div class=\"adK__panelFooter\" id=\"adK-chips\"></div>\n        </div>\n      </aside>\n\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const data = {\n    c1:{\n      title:\"Curriculum–Industry Gap\",\n      bullets:[\n        \"Academic programs often lag behind modern industry demands and emerging roles.\",\n        \"Limited exposure to Industry 4.0, lean innovation, AI application, and real-world problem-solving.\",\n        \"Students graduate knowledgeable but not job-ready, impacting outcomes for both learners and employers.\"\n      ],\n      chips:[\"Industry relevance\",\"Job readiness\",\"Future skills\"]\n    },\n    c2:{\n      title:\"Lack of Integrated Learning Approaches\",\n      bullets:[\n        \"Lean, Agile, Six Sigma, Design Thinking, and Digital Skills are taught in isolation or not at all.\",\n        \"Institutions struggle to combine technical, analytical, and behavioural competencies into a cohesive journey.\"\n      ],\n      chips:[\"Integrated curricula\",\"Holistic skillsets\",\"Applied learning\"]\n    },\n    c3:{\n      title:\"Faculty Capability & Resource Constraints\",\n      bullets:[\n        \"Faculty members lack access to current methodologies, tools, and global case studies.\",\n        \"Limited exposure to emerging technologies, digitalisation, and data-driven decision-making frameworks.\"\n      ],\n      chips:[\"Faculty development\",\"Modern content\",\"Digital exposure\"]\n    },\n    c4:{\n      title:\"Limited Exposure to Practical, Hands-on Methodologies\",\n      bullets:[\n        \"Students rarely get to solve real-life industry problems in a structured, mentored environment.\",\n        \"Training lacks simulations, live projects, digital labs, or experiential learning platforms.\"\n      ],\n      chips:[\"Experiential learning\",\"Live projects\",\"Labs & simulations\"]\n    },\n    c5:{\n      title:\"Absence of Structured Models for Employability & Future Skills\",\n      bullets:[\n        \"No streamlined frameworks to prepare graduates as Lean practitioners, innovators, or digital transformation leaders.\",\n        \"Institutions struggle to connect academic excellence with measurable employability and future-skills outcomes.\"\n      ],\n      chips:[\"Employability models\",\"Future skills frameworks\",\"Value-creator mindset\"]\n    }\n  };\n\n  const root = document.querySelector('#edu-challenges');\n  if(!root) return;\n\n  function applyMobileClass(){\n    const mqMobile = window.matchMedia && window.matchMedia('(max-width: 820px)').matches;\n\n    // Elementor responsive preview helpers\n    const elMobile =\n      document.body.classList.contains('elementor-device-mobile') ||\n      document.body.classList.contains('e--ua-device-mobile');\n\n    const mobile = mqMobile || elMobile;\n\n    root.classList.toggle('is-mobile', mobile);\n    return mobile;\n  }\n  applyMobileClass();\n  window.addEventListener('resize', applyMobileClass);\n\n  const tabs = Array.from(root.querySelectorAll('.adK__item'));\n  const fade = root.querySelector('#adK-fade');\n  const title = root.querySelector('#adK-title');\n  const bullets = root.querySelector('#adK-bullets');\n  const chips = root.querySelector('#adK-chips');\n\n  function isMobile(){\n    return (window.matchMedia && window.matchMedia('(max-width: 820px)').matches) || root.classList.contains('is-mobile');\n  }\n\n  function renderDesktop(key){\n    const d = data[key];\n    if(!d || !fade) return;\n\n    fade.classList.add('is-switching');\n    setTimeout(()=>{\n      title.textContent = d.title;\n\n      bullets.innerHTML = d.bullets.map(x =>\n        `<li><span class=\"adK__dot\"></span><span>${x}</span></li>`\n      ).join('');\n\n      chips.innerHTML = d.chips.map(x =>\n        `<span class=\"adK__chip\"><i></i>${x}</span>`\n      ).join('');\n\n      fade.classList.remove('is-switching');\n    }, 160);\n  }\n\n  function renderAccordionItem(btn){\n    const key = btn.dataset.key;\n    const d = data[key];\n    if(!d) return;\n\n    const acc = btn.querySelector('.adK__acc');\n    if(!acc) return;\n\n    acc.innerHTML = `\n      <ul class=\"adK__accBullets\">\n        ${d.bullets.map(x => `<li><span class=\"adK__dot\"></span><span>${x}</span></li>`).join('')}\n      </ul>\n      <div class=\"adK__accChips\">\n        ${d.chips.map(x => `<span class=\"adK__chip\"><i></i>${x}</span>`).join('')}\n      </div>\n    `;\n  }\n\n  tabs.forEach(btn => renderAccordionItem(btn));\n\n  function setActive(btn){\n    tabs.forEach(x=>{\n      x.setAttribute('aria-selected','false');\n      x.setAttribute('aria-expanded','false');\n    });\n    btn.setAttribute('aria-selected','true');\n\n    if(isMobile()){\n      btn.setAttribute('aria-expanded','true');\n    }else{\n      btn.setAttribute('aria-expanded','false');\n      renderDesktop(btn.dataset.key);\n    }\n  }\n\n  // Desktop default\n  renderDesktop('c1');\n\n  // Mobile: open first card by default\n  if(isMobile()){\n    tabs.forEach(x=>{\n      x.setAttribute('aria-selected','false');\n      x.setAttribute('aria-expanded','false');\n    });\n    if(tabs[0]){\n      tabs[0].setAttribute('aria-selected','true');\n      tabs[0].setAttribute('aria-expanded','true');\n    }\n  }\n\n  tabs.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      if(isMobile()){\n        const expanded = btn.getAttribute('aria-expanded') === 'true';\n        if(expanded){\n          btn.setAttribute('aria-expanded','false');\n          return;\n        }\n        tabs.forEach(x=>x.setAttribute('aria-expanded','false'));\n        btn.setAttribute('aria-expanded','true');\n\n        tabs.forEach(x=>x.setAttribute('aria-selected','false'));\n        btn.setAttribute('aria-selected','true');\n      }else{\n        setActive(btn);\n      }\n    });\n  });\n\n  window.addEventListener('resize', ()=>{\n    const active = tabs.find(x => x.getAttribute('aria-selected') === 'true') || tabs[0];\n    if(active && !isMobile()){\n      renderDesktop(active.dataset.key || 'c1');\n    }\n  });\n})();\n</script>\n\n<!-- ===================== EDUCATION — HOW WE CAN HELP (DESKTOP SLIDER + MOBILE ACCORDION) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#4B5168;\n  --line:rgba(49,59,134,.18);\n  --card:#ffffff;\n\n  /* ✅ update this for an education-themed background if you like */\n  --adw-bg-img:url(\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\");\n}\n\n/* scope */\n.adwS, .adwS *{ box-sizing:border-box; }\n\n.adwS{\n  position:relative;\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  color:var(--ink);\n  overflow:hidden;\n\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(31,156,228,.10), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.08), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.adwS::before{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(90deg, rgba(2,12,79,.80), rgba(2,12,79,.25) 55%, rgba(2,12,79,0) 100%),\n    var(--adw-bg-img);\n  background-size:cover;\n  background-position:center;\n  opacity:.95;\n  z-index:0;\n  pointer-events:none;\n}\n\n.adwS::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:linear-gradient(180deg, rgba(255,255,255,.06), rgba(255,255,255,.02));\n  z-index:0;\n  pointer-events:none;\n}\n\n.adwS__inner{\n  position:relative;\n  z-index:1;\n  max-width:1200px;\n  margin:0 auto;\n  width:100%;\n  min-width:0;\n}\n\n.adwS__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:rgba(255,255,255,.85);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.adwS__title{\n  margin:0 0 22px;\n  font-size:clamp(34px,4vw,56px);\n  line-height:1.08;\n  font-weight:900;\n  color:#fff;\n}\n\n.adwS__layout{\n  display:grid;\n  grid-template-columns:minmax(0,0.38fr) minmax(0,0.62fr);\n  gap:56px;\n  align-items:stretch;\n  width:100%;\n  min-width:0;\n}\n\n/* entrance animation */\n.adwS__left,\n.adwS__right{\n  opacity:0;\n  transition:opacity .85s ease, transform .85s cubic-bezier(.2,.9,.2,1);\n}\n.adwS__left{ transform:translateX(-44px); }\n.adwS__right{ transform:translateX(44px); }\n.adwS.is-in .adwS__left,\n.adwS.is-in .adwS__right{\n  opacity:1;\n  transform:translateX(0);\n}\n\n/* ===================== DESKTOP LEFT ===================== */\n.adwS__left{\n  border:1px solid rgba(255,255,255,.16);\n  border-radius:20px;\n  background:rgba(255,255,255,.06);\n  backdrop-filter: blur(10px);\n  box-shadow:0 12px 32px rgba(0,0,0,.14);\n  padding:18px;\n  min-width:0;\n}\n\n.adwS__leftTitle{\n  margin:0 0 12px;\n  font-size:26px;\n  font-weight:900;\n  color:#fff;\n}\n\n.adwS__nav{\n  display:grid;\n  gap:10px;\n  margin-top:10px;\n  min-width:0;\n}\n\n.adwS__navBtn{\n  width:100%;\n  border:1px solid rgba(255,255,255,.14);\n  background:rgba(255,255,255,.05);\n  border-radius:14px;\n  padding:14px 14px;\n  cursor:pointer;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n  text-align:left;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  min-width:0;\n  white-space:normal;\n}\n\n.adwS__navBtn:hover{\n  transform:translateY(-1px);\n  background:rgba(255,255,255,.07);\n  border-color:rgba(255,255,255,.18);\n}\n\n.adwS__navLeft{\n  display:flex;\n  align-items:center;\n  gap:10px;\n  min-width:0;\n  flex:1 1 auto;\n}\n\n.adwS__navMark{\n  width:10px; height:10px;\n  border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n  flex:0 0 auto;\n}\n\n.adwS__navText{ min-width:0; }\n\n.adwS__itemTitle{\n  margin:0;\n  font-size:14.5px;\n  font-weight:800;\n  color:#fff;\n  line-height:1.2;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.adwS__itemHint{\n  margin:6px 0 0;\n  font-size:12.5px;\n  color:rgba(255,255,255,.80);\n  line-height:1.3;\n  white-space:nowrap;\n  overflow:hidden;\n  text-overflow:ellipsis;\n}\n\n.adwS__navArrow{\n  width:34px; height:34px;\n  border-radius:12px;\n  display:grid;\n  place-items:center;\n  border:1px solid rgba(255,255,255,.16);\n  color:#fff;\n  background:rgba(255,255,255,.06);\n  flex:0 0 auto;\n}\n\n.adwS__navBtn[aria-selected=\"true\"]{\n  background:rgba(255,255,255,.10);\n  border-color:rgba(255,255,255,.24);\n}\n\n/* ===================== DESKTOP RIGHT SLIDER ===================== */\n.adwS__right{\n  position:relative;\n  border-radius:22px;\n  min-height:560px;\n  min-width:0;\n}\n\n.adwS__stage{\n  position:relative;\n  height:100%;\n  min-height:560px;\n  padding:0 68px; /* peeks */\n  min-width:0;\n}\n\n.adwS__card{\n  position:absolute;\n  top:0;\n  left:50%;\n  transform:translateX(-50%);\n  width:86%;\n  height:100%;\n  border-radius:22px;\n  background:rgba(255,255,255,.96);\n  border:1px solid rgba(49,59,134,.18);\n  box-shadow:0 28px 70px rgba(0,0,0,.22);\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  transition:transform .42s cubic-bezier(.2,.9,.2,1), opacity .25s ease;\n}\n\n.adwS__card.is-active{ z-index:3; opacity:1; }\n.adwS__card.is-prev,\n.adwS__card.is-next{\n  z-index:2;\n  width:82%;\n  opacity:.78;\n  background:rgba(255,255,255,.78);\n  box-shadow:0 22px 60px rgba(0,0,0,.18);\n}\n.adwS__card.is-prev{ transform:translateX(-50%) translateX(-110px) scale(.965); }\n.adwS__card.is-next{ transform:translateX(-50%) translateX(110px) scale(.965); }\n\n.adwS__top{\n  padding:18px 22px 14px;\n  border-bottom:1px solid rgba(49,59,134,.14);\n  background:\n    radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n    radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n    #fff;\n}\n\n.adwS__kicker{\n  margin:0 0 6px;\n  font-size:12px;\n  letter-spacing:.16em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:900;\n}\n\n.adwS__cardTitle{\n  margin:0;\n  font-size:22px;\n  line-height:1.2;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.adwS__body{\n  padding:16px 22px 18px;\n  overflow:auto;\n}\n\n.adwS__lead{\n  margin:0 0 12px;\n  font-size:15px;\n  line-height:1.75;\n  color:#2E334D;\n}\n\n.adwS__label{\n  margin:12px 0 8px;\n  font-size:14px;\n  font-weight:800;\n  color:var(--ink);\n}\n\n.adwS__list{ margin:0; padding-left:18px; }\n.adwS__list li{\n  margin:0 0 7px;\n  font-size:14.5px;\n  line-height:1.65;\n  color:#2E334D;\n}\n\n.adwS__impact{\n  margin-top:14px;\n  padding:12px 12px;\n  border-radius:14px;\n  border:1px solid rgba(49,59,134,.12);\n  background:rgba(49,59,134,.03);\n  border-left:4px solid var(--accent);\n  font-size:14.5px;\n  line-height:1.7;\n  color:#3C4160;\n}\n.adwS__impact b{ color:var(--navy); }\n\n/* peek preview */\n.adwS__card.is-prev .adwS__lead,\n.adwS__card.is-next .adwS__lead{\n  display:-webkit-box;\n  -webkit-line-clamp:2;\n  -webkit-box-orient:vertical;\n  overflow:hidden;\n  max-height:3.7em;\n}\n.adwS__card.is-prev .adwS__label,\n.adwS__card.is-next .adwS__label,\n.adwS__card.is-prev .adwS__list,\n.adwS__card.is-next .adwS__list,\n.adwS__card.is-prev .adwS__impact,\n.adwS__card.is-next .adwS__impact{\n  display:none;\n}\n\n.adwS__ctrl{\n  position:absolute;\n  top:50%;\n  transform:translateY(-50%);\n  width:46px;height:46px;\n  border-radius:14px;\n  border:1px solid rgba(255,255,255,.22);\n  background:rgba(0,0,0,.50);\n  color:#fff;\n  display:grid;\n  place-items:center;\n  cursor:pointer;\n  transition:transform .18s ease, background .18s ease, border-color .18s ease;\n  z-index:5;\n  user-select:none;\n}\n.adwS__ctrl:hover{\n  transform:translateY(-50%) scale(1.03);\n  background:rgba(255,255,255,.16);\n  border-color:rgba(255,255,255,.30);\n}\n.adwS__ctrl--prev{ left:12px; }\n.adwS__ctrl--next{ right:12px; }\n\n/* ===================== MOBILE DESIGN (NO HORIZONTAL ANYTHING) ===================== */\n.adwS__mWrap{ display:none; } /* only mobile */\n\n@media (max-width:980px){\n  .adwS{ padding:78px 16px; }\n  .adwS__layout{ grid-template-columns:1fr; gap:14px; }\n\n  /* hide desktop slider UI */\n  .adwS__right{ display:none !important; }\n\n  /* left card smaller */\n  .adwS__left{\n    padding:14px;\n    border-radius:18px;\n  }\n  .adwS__leftTitle{ font-size:18px; margin-bottom:10px; }\n\n  .adwS__nav{ display:none !important; }\n\n  /* show mobile accordion */\n  .adwS__mWrap{ display:grid; gap:12px; }\n\n  .adwS__mCard{\n    border:1px solid rgba(255,255,255,.18);\n    background:rgba(255,255,255,.08);\n    backdrop-filter: blur(10px);\n    border-radius:18px;\n    box-shadow:0 12px 28px rgba(0,0,0,.14);\n    overflow:hidden;\n  }\n\n  .adwS__mBtn{\n    width:100%;\n    border:0;\n    background:transparent;\n    padding:14px 14px;\n    display:flex;\n    align-items:center;\n    justify-content:space-between;\n    gap:12px;\n    cursor:pointer;\n    text-align:left;\n    color:#fff;\n  }\n\n  .adwS__mLeft{\n    display:flex;\n    align-items:flex-start;\n    gap:10px;\n    min-width:0;\n    flex:1 1 auto;\n  }\n\n  .adwS__mTitle{\n    margin:0;\n    font-size:14.5px;\n    font-weight:900;\n    line-height:1.25;\n    color:#fff;\n  }\n\n  .adwS__mHint{\n    margin:6px 0 0;\n    font-size:12.5px;\n    line-height:1.35;\n    color:rgba(255,255,255,.82);\n    overflow-wrap:anywhere;\n  }\n\n  .adwS__mChevron{\n    width:34px;height:34px;\n    border-radius:12px;\n    border:1px solid rgba(255,255,255,.16);\n    background:rgba(255,255,255,.06);\n    display:grid;\n    place-items:center;\n    color:#fff;\n    flex:0 0 auto;\n    transition:transform .2s ease;\n  }\n\n  .adwS__mAcc{\n    display:none;\n    padding:0 14px 14px;\n  }\n\n  .adwS__mCard[aria-expanded=\"true\"] .adwS__mAcc{ display:block; }\n  .adwS__mCard[aria-expanded=\"true\"] .adwS__mChevron{ transform:rotate(180deg); }\n\n  /* mobile content card (white) */\n  .adwS__mContent{\n    border-radius:16px;\n    background:rgba(255,255,255,.96);\n    border:1px solid rgba(49,59,134,.18);\n    box-shadow:0 18px 44px rgba(0,0,0,.18);\n    overflow:hidden;\n  }\n\n  .adwS__mTop{\n    padding:14px 14px 12px;\n    border-bottom:1px solid rgba(49,59,134,.14);\n    background:\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\n      radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\n      #fff;\n  }\n\n  .adwS__mKicker{\n    margin:0 0 6px;\n    font-size:11.5px;\n    letter-spacing:.14em;\n    text-transform:uppercase;\n    color:var(--indigo);\n    font-weight:900;\n  }\n\n  .adwS__mCardTitle{\n    margin:0;\n    font-size:20px;\n    line-height:1.2;\n    font-weight:950;\n    color:var(--navy);\n  }\n\n  .adwS__mBody{\n    padding:12px 14px 14px;\n  }\n\n  .adwS__mLead{\n    margin:0 0 10px;\n    font-size:14.5px;\n    line-height:1.7;\n    color:#2E334D;\n  }\n\n  .adwS__mLabel{\n    margin:10px 0 8px;\n    font-size:13.5px;\n    font-weight:900;\n    color:var(--ink);\n  }\n\n  .adwS__mList{\n    margin:0;\n    padding-left:18px;\n  }\n  .adwS__mList li{\n    margin:0 0 7px;\n    font-size:14.2px;\n    line-height:1.65;\n    color:#2E334D;\n    overflow-wrap:anywhere;\n  }\n\n  .adwS__mImpact{\n    margin-top:12px;\n    padding:10px 12px;\n    border-radius:14px;\n    border:1px solid rgba(49,59,134,.12);\n    background:rgba(49,59,134,.03);\n    border-left:4px solid var(--accent);\n    font-size:14.2px;\n    line-height:1.7;\n    color:#3C4160;\n  }\n  .adwS__mImpact b{ color:var(--navy); }\n}\n</style>\n\n<section class=\"adwS\" id=\"edu-how-we-help\" aria-label=\"How we help the Education sector\">\n  <div class=\"adwS__inner\">\n    <p class=\"adwS__eyebrow\">Education Sector</p>\n    <h2 class=\"adwS__title\">How We Can Help the Education Sector</h2>\n\n    <div class=\"adwS__layout\">\n      <!-- DESKTOP LEFT -->\n      <aside class=\"adwS__left\">\n        <h3 class=\"adwS__leftTitle\">Our Education Solutions</h3>\n\n        <div class=\"adwS__nav\" role=\"tablist\" aria-label=\"Education sector service pillars\">\n          <button class=\"adwS__navBtn\" role=\"tab\" aria-selected=\"true\" data-i=\"0\">\n            <div class=\"adwS__navLeft\">\n              <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"adwS__navText\">\n                <p class=\"adwS__itemTitle\">Growth &amp; Strategy for Institutions</p>\n                <p class=\"adwS__itemHint\">Future-ready programs &amp; positioning</p>\n              </div>\n            </div>\n            <span class=\"adwS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"adwS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"1\">\n            <div class=\"adwS__navLeft\">\n              <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"adwS__navText\">\n                <p class=\"adwS__itemTitle\">Capability Building for Students &amp; Faculty</p>\n                <p class=\"adwS__itemHint\">Lean &amp; digital leadership academies</p>\n              </div>\n            </div>\n            <span class=\"adwS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"adwS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"2\">\n            <div class=\"adwS__navLeft\">\n              <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"adwS__navText\">\n                <p class=\"adwS__itemTitle\">Tech-Enabled Transformation for Education</p>\n                <p class=\"adwS__itemHint\">Smart, digital learning ecosystems</p>\n              </div>\n            </div>\n            <span class=\"adwS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"adwS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"3\">\n            <div class=\"adwS__navLeft\">\n              <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"adwS__navText\">\n                <p class=\"adwS__itemTitle\">Shared Services, GCC &amp; Excellence Hubs</p>\n                <p class=\"adwS__itemHint\">Centres of excellence &amp; support hubs</p>\n              </div>\n            </div>\n            <span class=\"adwS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n\n          <button class=\"adwS__navBtn\" role=\"tab\" aria-selected=\"false\" data-i=\"4\">\n            <div class=\"adwS__navLeft\">\n              <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n              <div class=\"adwS__navText\">\n                <p class=\"adwS__itemTitle\">ESG &amp; Purpose-Led Value Creation</p>\n                <p class=\"adwS__itemHint\">Reputation, impact &amp; compliance</p>\n              </div>\n            </div>\n            <span class=\"adwS__navArrow\" aria-hidden=\"true\">›</span>\n          </button>\n        </div>\n\n        <!-- MOBILE ACCORDION -->\n        <div class=\"adwS__mWrap\" id=\"edu-how-we-help-mobile\"></div>\n      </aside>\n\n      <!-- DESKTOP RIGHT -->\n      <div class=\"adwS__right\">\n        <button class=\"adwS__ctrl adwS__ctrl--prev\" type=\"button\" aria-label=\"Previous\">‹</button>\n        <button class=\"adwS__ctrl adwS__ctrl--next\" type=\"button\" aria-label=\"Next\">›</button>\n\n        <div class=\"adwS__stage\" aria-live=\"polite\">\n          <article class=\"adwS__card is-prev\" id=\"edu-how-we-help-prev\"></article>\n          <article class=\"adwS__card is-active\" id=\"edu-how-we-help-active\"></article>\n          <article class=\"adwS__card is-next\" id=\"edu-how-we-help-next\"></article>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<script>\n(function(){\n  const section = document.getElementById('edu-how-we-help');\n  if(!section) return;\n\n  const isElementor =\n    document.body.classList.contains('elementor-editor-active') ||\n    document.body.classList.contains('elementor-editor-preview') ||\n    !!document.querySelector('#elementor-editor-wrapper');\n\n  function enter(){ section.classList.add('is-in'); }\n\n  if(isElementor){\n    enter();\n  } else if('IntersectionObserver' in window){\n    const io = new IntersectionObserver((entries)=>{\n      entries.forEach(e=>{\n        if(e.isIntersecting){\n          enter();\n          io.unobserve(section);\n        }\n      });\n    }, { threshold: 0.25 });\n    io.observe(section);\n    setTimeout(()=>{ if(!section.classList.contains('is-in')) enter(); }, 1200);\n  } else {\n    enter();\n  }\n\n  const data = [\n    {\n      navTitle:\"Growth & Strategy for Institutions\",\n      navHint:\"Future-ready programs & positioning\",\n      kicker:\"01 · Growth & Strategy for Educational Institutions\",\n      title:\"Designing Future-Ready Academic Strategy\",\n      lead:\"We help higher education institutions, universities, and skill bodies redesign their academic strategy to align with modern industry needs and future-of-work realities.\",\n      label1:\"We support:\",\n      bullets:[\n        \"New-age program design across Lean, Industry 4.0, Analytics, AI, and Digital Transformation\",\n        \"Industry-linked curriculum development with practical, applied focus\",\n        \"Skill development and employability frameworks integrated into academic journeys\",\n        \"Partnership strategies with industry, global universities, and technology partners\",\n        \"Revenue diversification through digital, executive, and continuing education offerings\"\n      ],\n      impact:\"Future-ready programs, stronger brand positioning, higher placements, and sharper industry relevance.\"\n    },\n    {\n      navTitle:\"Capability Building for Students & Faculty\",\n      navHint:\"Lean & digital leadership academies\",\n      kicker:\"02 · Capability Building: Creating Tomorrow’s Lean & Digital Leaders\",\n      title:\"Scalable Capability Building for Students and Faculty\",\n      lead:\"Inspired by QAI’s heritage of training over 70,000 professionals globally, we bring a modern, hybrid, scalable capability-building model tailored for students and faculty.\",\n      label1:\"We offer:\",\n      bullets:[\n        \"Lean Practitioner, Lean Leader, and Lean Six Sigma (Green Belt / Black Belt) programs\",\n        \"Industry 4.0 and Smart Manufacturing awareness and advanced certifications\",\n        \"Design Thinking and Innovation programs for structured problem-solving\",\n        \"Integrated DigiLean, Agile, and Problem-Solving academies for students and faculty\",\n        \"Value Creation and Entrepreneurship bootcamps\",\n        \"Faculty development programs in modern methodologies and tools\"\n      ],\n      impact:\"Students gain job-ready skills, faculty becomes future-ready, institutions strengthen placement outcomes, and employers receive graduates who can create value from Day One.\"\n    },\n    {\n      navTitle:\"Tech-Enabled Transformation for Education\",\n      navHint:\"Smart, digital learning ecosystems\",\n      kicker:\"03 · Tech-Enabled Transformation for Education\",\n      title:\"Modernising Learning Delivery and Campus Operations\",\n      lead:\"We help institutions modernise how learning is delivered and how campuses operate, using technology as an enabler of access, quality, and scale.\",\n      label1:\"Our support includes:\",\n      bullets:[\n        \"Digital learning platforms and LMS implementation\",\n        \"AI-driven assessment and personalised learning pathways\",\n        \"Data analytics for academic improvement and institutional operations\",\n        \"Digital content creation for Lean, Six Sigma, Industry 4.0, and leadership programs\",\n        \"Process digitisation across academic, examination, and administrative functions\"\n      ],\n      impact:\"Smarter, scalable, and accessible learning ecosystems built for 21st-century students.\"\n    },\n    {\n      navTitle:\"Shared Services, GCC & Excellence Hubs\",\n      navHint:\"Centres of excellence & support hubs\",\n      kicker:\"04 · Shared Services, GCC & Education Excellence Hubs\",\n      title:\"Building Education Excellence Hubs and Support Systems\",\n      lead:\"Educational institutions increasingly seek scalable support systems for research, digital, and operations. We design hubs that consolidate capability and strengthen student experience.\",\n      label1:\"We help design:\",\n      bullets:[\n        \"Centres of Excellence in Lean, AI, Industry 4.0, and Analytics\",\n        \"Academic GCCs for digital content, research, placements, and innovation support\",\n        \"Governance frameworks for multi-campus institutions and university systems\",\n        \"Standardisation of core processes across institutes and campuses\"\n      ],\n      impact:\"Higher efficiency, better student experience, and stronger institutional governance.\"\n    },\n    {\n      navTitle:\"ESG & Purpose-Led Value Creation\",\n      navHint:\"Reputation, impact & compliance\",\n      kicker:\"05 · ESG & Purpose-Led Value Creation for Institutions\",\n      title:\"Purpose-Led, ESG-Aligned Universities and Institutions\",\n      lead:\"We help universities adopt ESG-aligned frameworks that enhance reputation, compliance, and social impact while engaging students in purpose-led initiatives.\",\n      label1:\"We support:\",\n      bullets:[\n        \"Roadmaps for green campus transformation and resource efficiency\",\n        \"Sustainability reporting frameworks aligned to emerging expectations\",\n        \"Inclusion and diversity models for students, faculty, and staff\",\n        \"Purpose-led youth engagement initiatives and social impact programs\"\n      ],\n      impact:\"Stronger brand reputation, improved compliance, and campuses that embody the values they teach.\"\n    }\n  ];\n\n  /* ---------------- DESKTOP SLIDER ---------------- */\n  const navButtons = Array.from(section.querySelectorAll('.adwS__navBtn'));\n  const prevEl = section.querySelector('#edu-how-we-help-prev');\n  const activeEl = section.querySelector('#edu-how-we-help-active');\n  const nextEl = section.querySelector('#edu-how-we-help-next');\n  const btnPrev = section.querySelector('.adwS__ctrl--prev');\n  const btnNext = section.querySelector('.adwS__ctrl--next');\n\n  let idx = 0;\n\n  function cardHTML(d){\n    return `\n      <div class=\"adwS__top\">\n        <p class=\"adwS__kicker\">${d.kicker}</p>\n        <h3 class=\"adwS__cardTitle\">${d.title}</h3>\n      </div>\n      <div class=\"adwS__body\">\n        <p class=\"adwS__lead\">${d.lead}</p>\n        <div class=\"adwS__label\">${d.label1}</div>\n        <ul class=\"adwS__list\">\n          ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n        </ul>\n        <div class=\"adwS__impact\"><b>Impact:</b> ${d.impact}</div>\n      </div>\n    `;\n  }\n\n  function setActiveNav(i){\n    navButtons.forEach((b,bi)=> b.setAttribute('aria-selected', bi===i ? 'true':'false'));\n  }\n\n  function renderDesktop(){\n    const prevI = (idx - 1 + data.length) % data.length;\n    const nextI = (idx + 1) % data.length;\n\n    if(prevEl) prevEl.innerHTML = cardHTML(data[prevI]);\n    if(activeEl) activeEl.innerHTML = cardHTML(data[idx]);\n    if(nextEl) nextEl.innerHTML = cardHTML(data[nextI]);\n    setActiveNav(idx);\n  }\n\n  function goTo(i){\n    idx = (i + data.length) % data.length;\n    renderDesktop();\n  }\n\n  navButtons.forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      const i = parseInt(btn.getAttribute('data-i'),10);\n      goTo(i);\n    });\n  });\n\n  btnPrev && btnPrev.addEventListener('click', ()=> goTo(idx-1));\n  btnNext && btnNext.addEventListener('click', ()=> goTo(idx+1));\n\n  section.addEventListener('keydown', (e)=>{\n    if(e.key === 'ArrowLeft') goTo(idx-1);\n    if(e.key === 'ArrowRight') goTo(idx+1);\n  });\n\n  renderDesktop();\n\n  /* ---------------- MOBILE ACCORDION ---------------- */\n  const mobileMount = section.querySelector('#edu-how-we-help-mobile');\n\n  function mobileCard(d, i){\n    return `\n      <div class=\"adwS__mCard\" aria-expanded=\"${i===0 ? 'true':'false'}\" data-i=\"${i}\">\n        <button class=\"adwS__mBtn\" type=\"button\" aria-label=\"${d.navTitle}\">\n          <div class=\"adwS__mLeft\">\n            <span class=\"adwS__navMark\" aria-hidden=\"true\"></span>\n            <div style=\"min-width:0\">\n              <p class=\"adwS__mTitle\">${d.navTitle}</p>\n              <p class=\"adwS__mHint\">${d.navHint}</p>\n            </div>\n          </div>\n          <span class=\"adwS__mChevron\" aria-hidden=\"true\">⌄</span>\n        </button>\n\n        <div class=\"adwS__mAcc\">\n          <div class=\"adwS__mContent\">\n            <div class=\"adwS__mTop\">\n              <p class=\"adwS__mKicker\">${d.kicker}</p>\n              <h3 class=\"adwS__mCardTitle\">${d.title}</h3>\n            </div>\n            <div class=\"adwS__mBody\">\n              <p class=\"adwS__mLead\">${d.lead}</p>\n              <div class=\"adwS__mLabel\">${d.label1}</div>\n              <ul class=\"adwS__mList\">\n                ${d.bullets.map(x=>`<li>${x}</li>`).join('')}\n              </ul>\n              <div class=\"adwS__mImpact\"><b>Impact:</b> ${d.impact}</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    `;\n  }\n\n  function renderMobile(){\n    if(!mobileMount) return;\n    mobileMount.innerHTML = data.map((d,i)=>mobileCard(d,i)).join('');\n\n    const cards = Array.from(mobileMount.querySelectorAll('.adwS__mCard'));\n    cards.forEach(card=>{\n      const btn = card.querySelector('.adwS__mBtn');\n      btn.addEventListener('click', ()=>{\n        const isOpen = card.getAttribute('aria-expanded') === 'true';\n        cards.forEach(c=>c.setAttribute('aria-expanded','false'));\n        card.setAttribute('aria-expanded', isOpen ? 'false' : 'true');\n      });\n    });\n  }\n\n  renderMobile();\n})();\n</script>\n\n<!-- ===================== EDUCATION — COLLABORATION + WHY CHOOSE US (IMAGE LEFT) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n}\n\n/* SECTION */\n.adw, .adw *{box-sizing:border-box;}\n.adw{\n  padding:96px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:\n    radial-gradient(circle at 18% 0%, rgba(98,90,216,.08), transparent 55%),\n    radial-gradient(circle at 95% 30%, rgba(49,59,134,.08), transparent 55%),\n    radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\n    rgba(49,59,134,.03);\n}\n\n.adw__inner{\n  max-width:1200px;\n  margin:0 auto;\n  display:grid;\n  grid-template-columns:1.05fr 0.95fr; /* image slightly wider */\n  gap:44px;\n  align-items:stretch; /* equal height */\n}\n\n/* IMAGE COLUMN */\n.adw__imageWrap{\n  position:relative;\n  border-radius:26px;\n  overflow:hidden;\n  min-height:520px; /* a bit taller to fit both blocks nicely */\n  box-shadow:0 22px 54px rgba(0,0,0,.10);\n}\n\n.adw__imageWrap img{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  object-fit:cover; /* ✅ full image, no gap */\n  display:block;\n}\n\n/* subtle brand overlay */\n.adw__imageWrap::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  background:\n    linear-gradient(180deg, rgba(2,12,79,.18), rgba(2,12,79,.08) 55%, rgba(255,255,255,0) 100%),\n    radial-gradient(circle at 20% 20%, rgba(98,90,216,.20), transparent 60%),\n    radial-gradient(circle at 80% 35%, rgba(31,156,228,.16), transparent 60%);\n  pointer-events:none;\n}\n\n/* CONTENT COLUMN */\n.adw__content{\n  display:flex;\n  flex-direction:column;\n  justify-content:center;\n}\n\n.adw__eyebrow{\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n  margin:0 0 10px;\n}\n\n.adw__title{\n  font-size:clamp(32px,3.6vw,46px);\n  line-height:1.1;\n  font-weight:900;\n  color:var(--navy);\n  margin:0 0 12px;\n}\n\n.adw__lead{\n  margin:0 0 18px;\n  font-size:15px;\n  line-height:1.75;\n  color:var(--muted);\n}\n\n/* MANIFESTO LIST */\n.adw__list{\n  list-style:none;\n  margin:0;\n  padding:0;\n  display:grid;\n  gap:18px;\n  position:relative;\n}\n\n/* vertical guide */\n.adw__list::before{\n  content:\"\";\n  position:absolute;\n  left:14px;\n  top:6px;\n  bottom:6px;\n  width:2px;\n  background:linear-gradient(180deg, rgba(98,90,216,.45), rgba(31,156,228,.35));\n  opacity:.6;\n}\n\n.adw__item{\n  position:relative;\n  padding-left:46px;\n}\n\n.adw__dot{\n  position:absolute;\n  left:6px;\n  top:4px;\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  background:#fff;\n  border:1px solid rgba(49,59,134,.25);\n}\n\n.adw__dot::after{\n  content:\"\";\n  position:absolute;\n  inset:4px;\n  border-radius:50%;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.12);\n}\n\n.adw__h{\n  margin:0 0 4px;\n  font-size:16px;\n  font-weight:800;\n  color:var(--navy);\n}\n\n.adw__p{\n  margin:0;\n  font-size:14.8px;\n  line-height:1.75;\n  color:#3C4160;\n}\n\n/* subtle separator between blocks */\n.adw__divider{\n  height:1px;\n  background:rgba(49,59,134,.14);\n  border:0;\n  margin:22px 0 18px;\n}\n\n/* MOBILE */\n@media(max-width:980px){\n  .adw{padding:78px 18px;}\n  .adw__inner{grid-template-columns:1fr; gap:26px;}\n  .adw__imageWrap{min-height:260px;}\n  .adw__list::before{left:12px;}\n}\n</style>\n\n<section class=\"adw\" id=\"edu-collab-why\">\n  <div class=\"adw__inner\">\n\n    <!-- IMAGE LEFT -->\n    <div class=\"adw__imageWrap\">\n      <img\n        src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg\"\n        alt=\"Education ecosystem collaboration\"\n      />\n    </div>\n\n    <!-- CONTENT RIGHT -->\n    <div class=\"adw__content\">\n      <p class=\"adw__eyebrow\">Education Sector</p>\n     \n      </ul>\n\n      <hr class=\"adw__divider\"/>\n\n      <h2 class=\"adw__title\" style=\"margin-top:0;\">Why Institutions Choose Us</h2>\n\n      <ul class=\"adw__list\">\n        <li class=\"adw__item\">\n          <span class=\"adw__dot\"></span>\n          <p class=\"adw__h\">Integrated Approach Across Lean, Digital &amp; Strategy</p>\n          <p class=\"adw__p\">One coherent system—curriculum, capability, operations, and outcomes—working together.</p>\n        </li>\n\n        <li class=\"adw__item\">\n          <span class=\"adw__dot\"></span>\n          <p class=\"adw__h\">Deep Capability in Experiential Learning</p>\n          <p class=\"adw__p\">Grounded in proven learning models, real-world tools, benchmarks, and case studies (inspired by QAI’s long legacy).</p>\n        </li>\n\n        <li class=\"adw__item\">\n          <span class=\"adw__dot\"></span>\n          <p class=\"adw__h\">Tech-Enabled, Future-Ready Learning</p>\n          <p class=\"adw__p\">Digital-first, hybrid, scalable frameworks built to reach thousands of students with quality.</p>\n        </li>\n\n        <li class=\"adw__item\">\n          <span class=\"adw__dot\"></span>\n          <p class=\"adw__h\">Strong Focus on Employability &amp; Future Skills</p>\n          <p class=\"adw__p\">Curriculum aligned with what employers actually demand—so graduates are job-ready.</p>\n        </li>\n\n        <li class=\"adw__item\">\n          <span class=\"adw__dot\"></span>\n          <p class=\"adw__h\">Collaborative, Long-Term Partnership Philosophy</p>\n          <p class=\"adw__p\">We co-create, co-deliver, and co-transform institutions—building capability that lasts.</p>\n        </li>\n      </ul>\n\n      <p class=\"adw__lead\" style=\"margin-top:18px;\">\n        <b>Our goal:</b> Build the next generation of Lean thinkers, Industry 4.0 innovators, digital leaders, and value creators who will transform India.\n      </p>\n    </div>\n\n  </div>\n</section>\n\n<!-- ===================== EDUCATION — FINAL CTA (WHITE BACKGROUND STRIP) ===================== -->\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\"/>\n\n<style>\n:root{\n  --navy:#020C4F;\n  --indigo:#313B86;\n  --violet:#625AD8;\n  --accent:#1F9CE4;\n\n  --ink:#0B0F1A;\n  --muted:#3C4160;\n  --line:rgba(49,59,134,.16);\n}\n\n.ad-cta, .ad-cta *{box-sizing:border-box;}\n.ad-cta{\n  padding:84px 20px;\n  font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\n  background:#ffffff; /* white, consistent with other sectors */\n}\n\n.ad-cta__inner{\n  max-width:1200px;\n  margin:0 auto;\n}\n\n.ad-cta__bar{\n  border:1px solid rgba(49,59,134,.16);\n  border-radius:26px;\n  background:rgba(255,255,255,.98);\n  box-shadow:0 22px 54px rgba(0,0,0,.08);\n  padding:28px 28px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:22px;\n}\n\n.ad-cta__left{\n  min-width:0;\n  max-width:820px;\n}\n\n.ad-cta__kicker{\n  margin:0 0 10px;\n  font-size:12px;\n  letter-spacing:.18em;\n  text-transform:uppercase;\n  color:var(--indigo);\n  font-weight:800;\n}\n\n.ad-cta__title{\n  margin:0 0 10px;\n  font-size:clamp(26px,3.2vw,38px);\n  line-height:1.15;\n  font-weight:900;\n  color:var(--navy);\n}\n\n.ad-cta__text{\n  margin:0;\n  font-size:15.5px;\n  line-height:1.75;\n  color:var(--muted);\n}\n\n/* signal pill */\n.ad-cta__pill{\n  display:inline-flex;\n  align-items:center;\n  gap:10px;\n  padding:9px 12px;\n  border-radius:999px;\n  border:1px solid rgba(49,59,134,.18);\n  background:rgba(49,59,134,.04);\n  color:var(--indigo);\n  font-weight:800;\n  font-size:12px;\n  margin-top:14px;\n  flex-wrap:wrap;\n}\n\n.ad-cta__dot{\n  width:9px;height:9px;border-radius:999px;\n  background:linear-gradient(135deg,var(--violet),var(--accent));\n  box-shadow:0 0 0 6px rgba(31,156,228,.10);\n}\n\n.ad-cta__right{\n  flex:0 0 auto;\n  display:flex;\n  gap:12px;\n  flex-wrap:wrap;\n  justify-content:flex-end;\n}\n\n.ad-cta__btn{\n  height:46px;\n  padding:0 18px;\n  border-radius:999px;\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:10px;\n  font-size:14px;\n  font-weight:800;\n  text-decoration:none;\n  transition:.2s ease;\n  white-space:nowrap;\n}\n\n.ad-cta__btn--primary{\n  background:var(--violet);\n  color:#fff;\n  border:1px solid var(--violet);\n  box-shadow:0 12px 26px rgba(98,90,216,.22);\n}\n.ad-cta__btn--primary:hover{\n  background:var(--accent);\n  border-color:var(--accent);\n  transform:translateY(-1px);\n}\n\n.ad-cta__btn--ghost{\n  background:#fff;\n  color:var(--navy);\n  border:1px solid rgba(49,59,134,.22);\n}\n.ad-cta__btn--ghost:hover{\n  background:rgba(49,59,134,.04);\n  transform:translateY(-1px);\n}\n\n@media (max-width:980px){\n  .ad-cta{padding:70px 18px;}\n  .ad-cta__bar{\n    padding:22px;\n    flex-direction:column;\n    align-items:flex-start;\n  }\n  .ad-cta__right{justify-content:flex-start;}\n}\n</style>\n\n<section class=\"ad-cta\" id=\"edu-cta\">\n  <div class=\"ad-cta__inner\">\n\n    <div class=\"ad-cta__bar\">\n      <div class=\"ad-cta__left\">\n        <p class=\"ad-cta__kicker\">Next steps</p>\n        <h2 class=\"ad-cta__title\">Let’s Shape India’s Next Generation of Value Creators</h2>\n        <p class=\"ad-cta__text\">\n          From strategy and curriculum to digital enablement, capability-building, and employability, we partner with\n          universities, higher education institutions, and skill bodies to build learning ecosystems that are future-ready,\n          industry-linked, and deeply relevant for students.\n        </p>\n\n        <div class=\"ad-cta__pill\">\n          <span class=\"ad-cta__dot\" aria-hidden=\"true\"></span>\n          Lean • Industry 4.0 • Digital • Employability • Future Skills\n        </div>\n      </div>\n\n      <div class=\"ad-cta__right\">\n        <a class=\"ad-cta__btn ad-cta__btn--ghost\" href=\"/contact-us\">Explore partnership models</a>\n        <a class=\"ad-cta__btn ad-cta__btn--primary\" href=\"/contact-us\">Schedule a conversation →</a>\n      </div>\n    </div>\n\n  </div>\n</section>";
